def priority(task, state, m=10.0, p=1.0, a=1.0, b=0.5, eps=1e-6):
    est = max(task.estimated_runtime, eps)
    mean = max(state.mean_est, eps)
    load = state.queue_work / max(state.capacity * mean, eps)
    gate = load / (1.0 + load)
    free_ratio = state.free / max(state.capacity, eps)
    pressure = max(0.0, min(1.0, gate + b * (1.0 - free_ratio)))
    if task.tenant == 'premium':
        tier = 1.0 + (m - 1.0) * (1.0 + a * pressure)
    else:
        tier = 1.0
    return tier / max(est ** p, eps)  # tuned (m=17.4,p=0.526,a=2.04,b=0.252,eps=1.6e-06)

