def priority(task, state, m=10.0, p=1.0, q=0.5):
    est = max(task.estimated_runtime, 1e-6)
    tier = m if task.tenant == 'premium' else 1.0
    weight_term = max(task.weight, 1e-6) ** q
    return tier * weight_term / (est ** p)  # tuned (m=15.1,p=0.94,q=0.504)

def priority(task, state, m=10.0, a=0.0, w=0.0, b=0.03, t_map=1.0, t_reduce=1.0, t_join=1.0, t_other=1.0):
    est = max(task.estimated_runtime, 1e-6)
    cores = max(task.resource_need, 1e-6)
    tier = m if task.tenant == 'premium' else 1.0
    if task.task_type == 'map':
        typ = t_map
    elif task.task_type == 'reduce':
        typ = t_reduce
    elif task.task_type == 'join':
        typ = t_join
    else:
        typ = t_other
    wgt = max(task.weight, 1e-6) ** w
    wait = max(0.0, state.now - task.release)
    mean = max(state.mean_est, 1e-6)
    age = 1.0 + b * wait / mean
    return tier * typ * wgt * age / (est * max(cores, 1e-6) ** a)  # tuned (m=13.9,a=0,w=0,b=0.0268,t_map=1.44,t_reduce=0.489,t_join=0.357,t_other=1.6)

def priority(task, state, m=10.0, w=0.0, alpha=1.0):
    est = max(task.estimated_runtime, 1e-6)
    tier = m if task.tenant == 'premium' else 1.0
    wt = max(task.weight, 1e-6) ** w
    denom = max(est ** alpha, 1e-6)
    return tier * wt / denom  # tuned (m=3.26,w=0,alpha=0.259)
